#!/bin/bash
# gen_cases.sh -- rung N = 35, owner model (3,5,7,35) --nosig, base.cnf already generated by
#   python3 -B owner.py 3 5 7 35 base.cnf --names --nosig
# Cases of the 2x2 split (r = #occ B2 = {f1=5}, t = #occ S1 = {f1<=4}, q = #occ B1 = {f3=0}, u = #occ S2 = {f3>=1}):
#   A  c35_rle12_qle12 : B2<=12, B1<=12      (r in 10..12, q in 10..12)
#   B  c35_rle12_ule22 : B2<=12, S2<=22      (r in 10..12, q in 13..16)
#   C  c35_tle22_qle12 : S1<=22, B1<=12      (r in 13..16, q in 10..12)
#   D  c35_tle22_ule22 : S1<=22, S2<=22      (r in 13..16, q in 13..16)
#   F  c35_full        : uncubed reference   (S1:25 S2:25 B1:16 B2:16 ALL:35)
cd "$(dirname "$0")"
gen() { name=$1; shift; nice -n 10 python3 -B addrows.py base.cnf run/$name.cnf "$@" > run/$name.gen.log 2>&1; echo "rc=$? $(date)" >> run/$name.gen.log; }
gen c35_full        S1:25 S2:25 B1:16 B2:16 ALL:35
gen c35_rle12_qle12 S1:25 S2:25 B1:12 B2:12 ALL:35
gen c35_rle12_ule22 S1:25 S2:22 B1:16 B2:12 ALL:35
gen c35_tle22_qle12 S1:22 S2:25 B1:12 B2:16 ALL:35
gen c35_tle22_ule22 S1:22 S2:22 B1:16 B2:16 ALL:35
echo ALLDONE $(date) > run/gen_cases.done
